module sq2_seq101_moore_detector(clk,rst,din,detected); input clk,rst,din; output reg detected; reg [1:0] state,next_state; parameter S0=0,S1=1,S10=2,S101=3; always @(posedge clk or posedge rst) begin if(rst) state<=S0; else state<=next_state; end always @(*) begin case(state) S0:next_state=din?S1:S0; S1:next_state=din?S1:S10; S10:next_state=din?S101:S0; S101:next_state=din?S1:S10; default:next_state=S0; endcase end always @(*) begin detected=(state==S101); end endmodule
